<template><div class="panel"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px"><b>三级分类管理</b><el-button type="primary" @click="open(null)">新增一级分类</el-button></div><el-table :data="flat" border><el-table-column prop="name" label="分类名称"/><el-table-column prop="level" label="层级" width="90"><template #default="s">{{s.row.level}}级</template></el-table-column><el-table-column label="操作" width="240"><template #default="s"><el-button v-if="s.row.level<3" link type="primary" @click="open(s.row.id)">新增下级</el-button><el-button link @click="edit(s.row)">编辑</el-button><el-button link type="danger" @click="remove(s.row.id)">删除</el-button></template></el-table-column></el-table><el-dialog v-model="dialog" :title="form.parentId?'新增下级分类':'新增一级分类'" width="420px"><el-form><el-form-item label="名称"><el-input v-model="form.name"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup>import {computed,onMounted,reactive,ref} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import {api} from '../utils';const cats=ref([]),dialog=ref(false),form=reactive({id:null,parentId:null,name:''});const flat=computed(()=>cats.value.slice().sort((a,b)=>a.level-b.level||a.sort_order-b.sort_order||a.id-b.id));async function load(){cats.value=(await api.get('/categories')).data.items}function open(parentId){Object.assign(form,{id:null,parentId,name:''});dialog.value=true}function edit(r){Object.assign(form,{id:r.id,parentId:r.parent_id,name:r.name});dialog.value=true}async function save(){if(!form.name.trim())return;try{if(form.id)await api.put(`/categories/${form.id}`,{name:form.name});else await api.post('/categories',{parentId:form.parentId,name:form.name});ElMessage.success('保存成功');dialog.value=false;load()}catch(e){ElMessage.error(e.response?.data?.message||'保存失败')}}async function remove(id){await ElMessageBox.confirm('删除分类后，该分类树会发生变化，确定继续？','提示');try{await api.delete(`/categories/${id}`);ElMessage.success('删除成功');load()}catch(e){ElMessage.error(e.response?.data?.message||'删除失败')}}onMounted(load)</script>
